 "Compresiones eficaces": "Compresións eficaces",
 "<div style=\"font-size:60px;font-weight:800;color:#c8384b;line-height:1.05\">100-120</div><div style=\"font-size:23px;color:#381318\">compresiones por minuto</div>": "<div style=\"font-size:60px;font-weight:800;color:#c8384b;line-height:1.05\">100-120</div><div style=\"font-size:23px;color:#381318\">compresións por minuto</div>",
